window.polishAudit = (panels) => {
 const vis = e => e && !e.hidden && e.getClientRects().length && getComputedStyle(e).visibility !== 'hidden' && +getComputedStyle(e).opacity > 0.05;
 const t = document.querySelector('#toast'), out = [];
 if (t.classList.contains('on') && vis(t)) {
  const r = t.getBoundingClientRect();
  if (r.left < 0 || r.top < 0 || r.right > innerWidth || r.bottom > innerHeight) out.push('toast offscreen');
  for (const sel of ['.fl', '.nav', '.cbar', '.hint', '#insp.open', '.pop.open', '#rpdeck', ...panels])
   for (const e of document.querySelectorAll(sel)) { if (!vis(e)) continue; const q = e.getBoundingClientRect(); if (q.width && q.height && r.left < q.right && r.right > q.left && r.top < q.bottom && r.bottom > q.top) out.push('toast over ' + sel); }
 }
 return out;
}; true

window.benchAudit = () => {
 const visible = e => e.getClientRects().length && getComputedStyle(e).visibility !== 'hidden' && +getComputedStyle(e).opacity > 0;
 const hits = (a,b) => a.left < b.right && a.right > b.left && a.top < b.bottom && a.bottom > b.top;
 const issues = [], labels = [...document.querySelectorAll('.bench-pin-label,.bench-plate,.bench-zone-label,#benchOrder')].filter(visible);
 const obstacles = [...document.querySelectorAll('#benchCard,.chip,.hint,.egress')].filter(visible);
 labels.forEach((e,i) => {
  const r = e.getBoundingClientRect();
  if (r.left < 0 || r.right > innerWidth || r.top < 0 || r.bottom > innerHeight) issues.push('offscreen ' + e.textContent.slice(0,40));
  [...labels.slice(i+1),...obstacles].forEach(o => { if (hits(r,o.getBoundingClientRect())) issues.push(e.textContent.slice(0,30) + ' overlaps ' + (o.id || o.textContent.slice(0,30))); });
 });
 const card = document.querySelector('#benchCard');
 if (!card.hidden) {
  const r = card.getBoundingClientRect();
  if (r.left<0 || r.top<0 || r.right>innerWidth || r.bottom>innerHeight) issues.push('card offscreen');
  if (card.scrollHeight > card.clientHeight) issues.push('card scrolls');
 }
 return issues;
}; benchAudit()
